837→            Some("error") => "\x1b[31m",
838→            Some("warn") => "\x1b[33m",
839→            Some("info") => "\x1b[32m",
840→            Some("debug") => "\x1b[34m",
841→            _ => "\x1b[0m",
842→        };
843→        println!(
844→            "{} {}{}\x1b[0m {}",
845→            entry.timestamp.unwrap_or_default(),
846→            level_color,
847→            entry.level.unwrap_or_default(),
848→            entry.message
849→        );
850→    }
