async fn execute_link(args: &LinkArgs) -> Result<()> {
    let client = CloudClient::new()?;

    // Verify the app exists
    let app = client.get_app(&args.app).await?;

    // Save the link
    let link = CloudLink {
        org: app.org.clone(),
        app: app.name.clone(),
        app_id: Some(app.id),
        region: app.region,
        linked_at: Some(chrono::Utc::now().to_rfc3339()),
