}

async fn execute_images(args: &ImagesArgs) -> Result<()> {
    let client = CloudClient::new()?;
    let images_resp = client
        .list_container_images(args.channel.as_deref())
        .await?;

    if args.output == OutputFormat::Json {
        return write_json(&images_resp);
