        .await?;

    if args.output == OutputFormat::Json {
        return write_json(&deployment);
    }

    println!("Deploying to {app_name}...");
    println!(
        "\x1b[32m✓ Deployment {} started (status: {})\x1b[0m",
        deployment.id, deployment.status
    );

