        println!("  Status:  {}", deployment.status);
        if let Some(image) = &deployment.image_tag {
            println!("  Image:   {image}");
        }
        if let Some(replicas) = deployment.replicas {
            println!("  Replicas: {replicas}");
        }
        if let Some(created) = &deployment.created_at {
            println!("  Created: {created}");
