224→/// Generate a random 8-character auth code.
225→fn generate_auth_code() -> String {
226→    use rand::Rng;
227→    const CHARSET: &[u8] = b"REDACTED";
228→    let mut rng = rand::rng();
229→
230→    (0..8)
231→        .map(|_| {
232→            let idx = rng.random_range(0..CHARSET.len());
233→            CHARSET[idx] as char
234→        })
235→        .collect()
236→}
237→
238→/// Read org and app name from spicepod.yaml if it exists.
239→fn read_spicepod_metadata() -> (Option<String>, Option<String>) {
240→    let Ok(contents) = std::fs::read_to_string("spicepod.yaml") else {
241→        return (None, None);
242→    };
243→
244→    let Ok(yaml) = yaml::from_str::<yaml::Value>(&contents) else {
245→        return (None, None);
246→    };
247→
248→    let org_name = yaml
249→        .get("metadata")
250→        .and_then(|m| m.get("org"))
251→        .and_then(|o| o.as_str())
252→        .map(String::from);
253→
254→    let app_name = yaml.get("name").and_then(|n| n.as_str()).map(String::from);
255→
256→    (org_name, app_name)
257→}
258→
259→/// Auth context from Spice.ai API.
260→#[derive(Debug, serde::Deserialize)]
261→struct SpiceAuthContext {
262→    username: String,
263→    email: String,
264→    org_name: String,
265→    app_name: Option<String>,
266→    app_api_key: Option<String>,
267→}
268→
269→/// Get auth context from Spice.ai API.
270→async fn get_spice_auth_context(
271→    base_url: &str,
272→    access_token: &str,
273→    org_name: Option<&str>,
274→    app_name: Option<&str>,
275→) -> Result<SpiceAuthContext> {
276→    let mut url = format!("{base_url}/api/spice-cli/auth");
277→
278→    let mut params = Vec::new();
279→    if let Some(org) = org_name {
280→        params.push(format!("org_name={}", urlencoding::encode(org)));
281→    }
282→    if let Some(app) = app_name {
283→        params.push(format!("app_name={}", urlencoding::encode(app)));
284→    }
285→    if !params.is_empty() {
286→        url = format!("{url}?{}", params.join("&"));
287→    }
288→
289→    let client = reqwest::Client::new();
290→    let response = client
291→        .get(&url)
292→        .header("Authorization", format!("Bearer {access_token}"))
293→        .send()
294→        .await
295→        .map_err(|e| crate::error::Error::InvalidResponse {
296→            message: format!("Failed to get auth context: {e}"),
297→        })?;
298→
299→    if !response.status().is_success() {
300→        let text = response.text().await.unwrap_or_default();
301→        return Err(crate::error::Error::InvalidResponse {
302→            message: format!("Auth context request failed: {text}"),
303→        });
304→    }
305→
306→    // Parse the response - API returns nested org/app objects
307→    let body: serde_json::Value =
308→        response
309→            .json()
310→            .await
311→            .map_err(|e| crate::error::Error::InvalidResponse {
312→                message: format!("Failed to parse auth context: {e}"),
313→            })?;
314→
315→    Ok(SpiceAuthContext {
316→        username: body["username"].as_str().unwrap_or_default().to_string(),
317→        email: body["email"].as_str().unwrap_or_default().to_string(),
318→        org_name: body["org"]["name"].as_str().unwrap_or_default().to_string(),
319→        app_name: body["app"]["name"].as_str().map(String::from),
320→        app_api_key: body["app"]["api_key"].as_str().map(String::from),
321→    })
322→}
