222→/// Login to Databricks.
223→pub async fn login_databricks(_ctx: &RuntimeContext, args: DatabricksArgs) -> Result<()> {
224→    // Validate: either token OR both client-id and client-secret
225→    let has_token = args.token.is_some();
226→    let has_service_principal = args.client_id.is_some() && args.client_secret.is_some();
227→
228→    if has_token == has_service_principal {
229→        return Err(crate::error::Error::InvalidArgument {
230→            message: "You must provide either --token OR both --client-id and --client-secret for Databricks authentication.".to_string(),
231→        });
232→    }
233→
234→    let mut params: Vec<(&str, &str)> = Vec::new();
235→
236→    if let Some(ref token) = args.token {
237→        params.push((AUTH_PARAM_TOKEN, token));
238→    }
239→    if let Some(ref client_id) = args.client_id {
240→        params.push((AUTH_PARAM_CLIENT_ID, client_id));
241→    }
242→    if let Some(ref client_secret) = args.client_secret {
243→        params.push((AUTH_PARAM_CLIENT_SECRET, client_secret));
244→    }
245→
246→    // Optional cloud storage credentials
247→    if let Some(ref region) = args.aws_region {
248→        params.push((AUTH_PARAM_AWS_DEFAULT_REGION, region));
249→    }
250→    if let Some(ref key_id) = args.aws_access_key_id {
251→        params.push((AUTH_PARAM_AWS_ACCESS_KEY_ID, key_id));
252→    }
253→    if let Some(ref secret) = args.aws_secret_access_key {
254→        params.push((AUTH_PARAM_AWS_SECRET_ACCESS_KEY, secret));
255→    }
256→    if let Some(ref account_name) = args.azure_storage_account_name {
257→        params.push((AUTH_PARAM_AZURE_ACCOUNT_NAME, account_name));
258→    }
259→    if let Some(ref access_key) = args.azure_storage_access_key {
260→        params.push((AUTH_PARAM_AZURE_ACCESS_KEY, access_key));
261→    }
262→    if let Some(ref path) = args.google_service_account_path {
263→        params.push((AUTH_PARAM_GCP_SERVICE_ACCOUNT_KEY_PATH, path));
264→    }
265→
266→    merge_auth_config(AUTH_TYPE_DATABRICKS, &params)?;
267→
268→    println!("\x1b[32mSuccessfully configured credentials for Databricks\x1b[0m");
269→    Ok(())
270→}
