 17→//! Runtime context for managing Spice runtime installation and configuration.
 18→
 19→use crate::error::{
 20→    CreateDirectorySnafu, HomeDirectoryNotFoundSnafu, Result, RuntimeExecutionSnafu,
 21→    RuntimeNotInstalledSnafu, RuntimeVersionSnafu,
 22→};
