 28→
 29→/// Constants for Spice paths and filenames
 30→const DOT_SPICE: &str = ".spice";
 31→const SPICED_FILENAME: &str = "spiced";
 32→const SPICEPODS_DIR: &str = "spicepods";
 33→
 34→/// Runtime context holding paths and configuration for CLI operations.
 35→#[derive(Debug, Clone)]
 36→pub struct RuntimeContext {
 37→    /// Path to ~/.spice directory
 38→    spice_runtime_dir: PathBuf,
 39→
 40→    /// Path to ~/.spice/bin directory
 41→    spice_bin_dir: PathBuf,
 42→
 43→    /// Current working directory (app directory)
 44→    app_dir: PathBuf,
 45→
 46→    /// Path to spicepods directory in app (used by install/init commands)
 47→    pods_dir: PathBuf,
 48→
 49→    /// HTTP endpoint for runtime API
 50→    http_endpoint: String,
 51→
 52→    /// API key for authentication
 53→    api_key: Option<String>,
 54→
 55→    /// Whether to use cloud mode
 56→    is_cloud: bool,
 57→
 58→    /// User agent string for HTTP requests
 59→    user_agent: String,
 60→
 61→    /// Extra headers for HTTP requests
 62→    extra_headers: HashMap<String, String>,
 63→
 64→    /// HTTP client with default timeout
 65→    http_client: reqwest::Client,
 66→
 67→    /// TLS root certificate file path
 68→    tls_root_certificate_file: Option<String>,
 69→}
 70→
 71→impl RuntimeContext {
 72→    /// Create a new runtime context with default settings.
 73→    ///
 74→    /// # Errors
 75→    ///
 76→    /// Returns an error if the home directory cannot be determined.
 77→    pub fn new() -> Result<Self> {
 78→        let home_dir = dirs::home_dir().ok_or_else(|| HomeDirectoryNotFoundSnafu.build())?;
 79→        let spice_runtime_dir = home_dir.join(DOT_SPICE);
 80→        let spice_bin_dir = spice_runtime_dir.join("bin");
 81→
 82→        let app_dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
 83→        let pods_dir = app_dir.join(SPICEPODS_DIR);
 84→
 85→        let http_client = reqwest::Client::builder()
 86→            .timeout(Duration::from_secs(30))
 87→            .build()
 88→            .unwrap_or_default();
 89→
 90→        Ok(Self {
 91→            spice_runtime_dir,
 92→            spice_bin_dir,
 93→            app_dir,
 94→            pods_dir,
 95→            http_endpoint: "http://127.0.0.1:8090".to_string(),
 96→            api_key: None,
 97→            is_cloud: false,
 98→            user_agent: Self::default_user_agent(),
 99→            extra_headers: HashMap::new(),
100→            http_client,
101→            tls_root_certificate_file: None,
102→        })
103→    }
104→
105→    /// Create a runtime context from CLI arguments.
106→    pub fn with_args(
107→        http_endpoint: Option<String>,
108→        api_key: Option<String>,
109→        is_cloud: bool,
110→        tls_root_certificate_file: Option<String>,
111→    ) -> Result<Self> {
112→        let mut ctx = Self::new()?;
113→
114→        if let Some(endpoint) = http_endpoint {
115→            ctx.http_endpoint = endpoint;
116→        }
117→
118→        if is_cloud {
119→            ctx.http_endpoint = "https://data.spiceai.io".to_string();
120→            ctx.is_cloud = true;
121→        }
122→
123→        ctx.api_key = api_key;
124→        ctx.tls_root_certificate_file = tls_root_certificate_file;
125→
126→        // Load API key from .env if not provided
127→        if ctx.api_key.is_none() {
128→            ctx.api_key = ctx.load_api_key_from_env();
129→        }
130→
131→        Ok(ctx)
132→    }
133→
134→    /// Generate the default user agent string.
135→    fn default_user_agent() -> String {
136→        format!(
137→            "spice/{} ({}; {})",
138→            env!("CARGO_PKG_VERSION"),
139→            std::env::consts::OS,
140→            std::env::consts::ARCH
141→        )
142→    }
143→
144→    /// Load API key from .env or .env.local file.
145→    fn load_api_key_from_env(&self) -> Option<String> {
146→        // Try .env.local first, then .env
147→        let env_files = [".env.local", ".env"];
148→
149→        for env_file in &env_files {
150→            let path = self.app_dir.join(env_file);
151→            if path.exists()
152→                && let Ok(env_map) = dotenvy::from_path_iter(&path)
153→            {
154→                for item in env_map.flatten() {
155→                    if item.0 == "SPICE_SPICEAI_API_KEY" || item.0 == "SPICE_API_KEY" {
156→                        return Some(item.1);
157→                    }
158→                }
159→            }
160→        }
161→
162→        // Also check environment variables
163→        std::env::var("SPICE_API_KEY")
164→            .or_else(|_| std::env::var("SPICE_SPICEAI_API_KEY"))
165→            .ok()
166→    }
